-- ---------------------------------------------------------------------------
-- Source stream: airport_rate (raw) -> queue fl-cp-rate-weather-watch-airport_rate
-- Subscriptions: TTP/airportInfo/>
-- ---------------------------------------------------------------------------
CREATE TABLE airport_rate_raw (
    data         VARCHAR,
    solace_topic VARCHAR   DEFAULT CAST(CONNECTOR_METADATA()['solace_topic'] AS VARCHAR),
    airport      VARCHAR   DEFAULT CAST(CONNECTOR_METADATA()['airport'] AS VARCHAR),
    broker_ts    TIMESTAMP DEFAULT CAST(CONNECTOR_METADATA()['broker_ts'] AS TIMESTAMP)
) WITH ('append_only' = 'true', 'connectors' = '[
    {
        "name": "cp-rate-weather-watch-airport_rate",
        "transport": {
            "name": "solace_input",
            "config": {
                "host": "solace",
                "port": 55555,
                "vpn": "default",
                "username": "default",
                "password": "default",
                "queue": "fl-cp-rate-weather-watch-airport_rate",
                "include_topic": true,
                "include_broker_timestamp": true,
                "topic_pattern": "TTP/airportInfo/{airport}"
            }
        },
        "format": {
            "name": "raw",
            "config": {
                "column_name": "data"
            }
        }
    }
]');

CREATE VIEW airport_rate_events AS
SELECT
    airport,
    CAST(PARSE_JSON(data)['aar']            AS INTEGER)   AS aar,
    CAST(PARSE_JSON(data)['adr']            AS INTEGER)   AS adr,
    CAST(PARSE_JSON(data)['runway_config']  AS VARCHAR)   AS runway_config,
    CAST(PARSE_JSON(data)['effective_time'] AS TIMESTAMP) AS valid_from
FROM airport_rate_raw
WHERE airport IS NOT NULL;

LATENESS airport_rate_events.valid_from INTERVAL '2' HOUR;

CREATE MATERIALIZED VIEW airport_rate AS
SELECT
    airport, aar, adr, runway_config, valid_from,
    LEAD(valid_from) OVER (PARTITION BY airport ORDER BY valid_from) AS valid_to
FROM airport_rate_events;

-- ---------------------------------------------------------------------------
-- Source stream: weather (raw) -> queue fl-cp-rate-weather-watch-weather
-- Subscriptions: aviation/metar/>
-- ---------------------------------------------------------------------------
CREATE TABLE metar_latest_raw (
    data       VARCHAR,
    station_id VARCHAR DEFAULT CAST(CONNECTOR_METADATA()['station_id'] AS VARCHAR)
) WITH ('append_only' = 'true', 'connectors' = '[
    {
        "name": "cp-rate-weather-watch-weather",
        "transport": {
            "name": "solace_input",
            "config": {
                "host": "solace",
                "port": 55555,
                "vpn": "default",
                "username": "default",
                "password": "default",
                "queue": "fl-cp-rate-weather-watch-weather",
                "topic_pattern": "aviation/metar/{station_id}"
            }
        },
        "format": {
            "name": "raw",
            "config": {
                "column_name": "data"
            }
        }
    }
]');

CREATE MATERIALIZED VIEW metar_latest AS
SELECT station_id, observed_at, flight_category, wind_dir_degrees, wind_speed_kt,
       visibility_sm, wx_string
FROM (
    SELECT
        CAST(PARSE_JSON(data)['icaoId'] AS VARCHAR)       AS station_id,
        CAST(PARSE_JSON(data)['reportTime'] AS TIMESTAMP) AS observed_at,
        CAST(PARSE_JSON(data)['fltCat'] AS VARCHAR)       AS flight_category,
        CASE WHEN CAST(PARSE_JSON(data)['wdir'] AS VARCHAR) RLIKE '^[0-9]+$'
             THEN CAST(PARSE_JSON(data)['wdir'] AS INTEGER) END AS wind_dir_degrees,
        CAST(PARSE_JSON(data)['wspd'] AS INTEGER)         AS wind_speed_kt,
        CAST(PARSE_JSON(data)['visib'] AS VARCHAR)        AS visibility_sm,
        CAST(PARSE_JSON(data)['rawOb'] AS VARCHAR)        AS wx_string,
        ROW_NUMBER() OVER (PARTITION BY CAST(PARSE_JSON(data)['icaoId'] AS VARCHAR)
                           ORDER BY CAST(PARSE_JSON(data)['reportTime'] AS TIMESTAMP) DESC) AS rn
    FROM metar_latest_raw
) WHERE rn = 1;

-- ---------------------------------------------------------------------------
-- Data product: Rate Weather Watch (rate-weather-watch)
-- Airports with an AAR of 40 or less, with the latest weather category
-- ---------------------------------------------------------------------------
CREATE MATERIALIZED VIEW rate_weather_watch AS
SELECT r.airport, r.aar, r.runway_config, r.valid_from, w.flight_category
FROM airport_rate r
LEFT JOIN metar_latest w ON w.station_id = r.airport
WHERE r.aar <= 40;

-- Live changelog of rate_weather_watch -> fl/cp/rate-weather-watch/live/{airport} (full changelog: inserts and deletes)
CREATE MATERIALIZED VIEW rate_weather_watch_live_sink
WITH ('connectors' = '[{
    "name": "cp-rate-weather-watch-live",
    "transport": {
        "name": "solace_output",
        "config": {
            "host":     "solace",
            "port":     55555,
            "vpn":      "default",
            "username": "default",
            "password": "default",
            "topic":    "fl/cp/rate-weather-watch/live/{airport}",
            "delivery_mode": "direct"
        }
    },
    "format": {"name": "json"}
}]')
AS SELECT
    COALESCE(CAST(airport AS VARCHAR), 'unknown') AS airport,
    aar,
    runway_config,
    valid_from,
    flight_category
FROM rate_weather_watch;

-- Trigger 'low-vis' on rate_weather_watch -> fl/cp/rate-weather-watch/low-vis/{airport}
-- Low published rate while weather is IFR
CREATE MATERIALIZED VIEW trg_rate_weather_watch_low_vis
WITH ('connectors' = '[{
    "name": "trg-rate-weather-watch-low-vis",
    "transport": {
        "name": "solace_output",
        "config": {
            "host":     "solace",
            "port":     55555,
            "vpn":      "default",
            "username": "default",
            "password": "default",
            "topic":    "fl/cp/rate-weather-watch/low-vis/{airport}",
            "delivery_mode": "direct"
        }
    },
    "format": {"name": "json", "config": {"skip_deletes": true}}
}]')
AS SELECT DISTINCT
    COALESCE(CAST(airport AS VARCHAR), 'unknown') AS airport,
    aar,
    runway_config,
    flight_category
FROM rate_weather_watch
WHERE (flight_category = 'IFR')
  AND NOW() <= valid_from + INTERVAL '5' MINUTE
;
